import json
def transform(g):
    g=[r[:] for r in g]
    h,w=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    # rule 1: horizontal line rows (a row starting with a non-bg color, with a complete reference row)
    for line in [c for c in cnt if c!=bg]:
        rows=[r for r in range(h) if g[r][0]==line]
        refrows=[r for r in rows if g[r].count(line)==w]
        if len(rows)>1 and refrows:
            ref=g[refrows[0]]
            for r in rows:
                for c in range(w):
                    if g[r][c]!=ref[c]: g[r][c]=1
            return g
    # rule 2: repeating non-constant row segments between constant separator runs
    const=[all(x==g[r][0] for x in g[r]) for r in range(h)]
    segs=[]; cur=None
    for r in range(h):
        if not const[r]:
            if cur is None: cur=[r,r]
            else: cur[1]=r
        else:
            if cur is not None: segs.append(cur); cur=None
    if cur is not None: segs.append(cur)
    if len(segs)>1:
        ref=segs[0]; rl=ref[1]-ref[0]+1
        for s in segs[1:]:
            if s[1]-s[0]+1==rl:
                for i in range(rl):
                    for c in range(w):
                        if g[s[0]+i][c]!=g[ref[0]+i][c]: g[s[0]+i][c]=1
        return g
    return g

